code_example:
#include <string>
#include <iostream>

int main() {
    // Create a string from a C-style string with specified length
    std::string str1("Hello, World", 5); // 'Hello'
    // Create a string from a C-style string with default allocator
    std::string str2("Sample text"); // 'Sample text'
    // Create a string of 10 asterisks using default allocator
    std::string str3(10, '*'); // '**********'
    // Output the created strings
    std::cout << str1 << std::endl;
    std::cout << str2 << std::endl;
    std::cout << str3 << std::endl;
    return 0;
}
